mapper.sql:
FROM TB_POINT_LEDGER L
JOIN TB_POINT P ON L.POINTID = P.POINTID
WHERE P.MEMID = #{memId}

    AND L.EARNEDAT >= #{startDate}


    AND L.EARNEDAT <= #{endDate}

mapper.select:
SELECT NVL(TOTALPOINT, 0)
FROM TB_POINT
WHERE MEMID = #{memId}

SELECT NVL(SUM(amount), 0) FROM (
    SELECT L.AMOUNT AS amount,
           ROW_NUMBER() OVER (ORDER BY L.EARNEDAT DESC, L.LEGID DESC) AS RN


) SUB
WHERE RN <= #{offset}

SELECT NVL(SUM(L.AMOUNT), 0)
FROM TB_POINT_LEDGER L
JOIN TB_POINT P ON L.POINTID = P.POINTID
WHERE P.MEMID = #{memId}

    AND L.EARNEDAT >= #{startDate}


    AND L.EARNEDAT <= #{endDate}

AND L.AMOUNT > 0

SELECT NVL(SUM(L.AMOUNT), 0)
FROM TB_POINT_LEDGER L
JOIN TB_POINT P ON L.POINTID = P.POINTID
WHERE P.MEMID = #{memId}

    AND L.EARNEDAT >= #{startDate}


    AND L.EARNEDAT <= #{endDate}

AND L.AMOUNT < 0
